local json=require("braincloud.lib.json")local Http=require("braincloud.platform.http")local crypto=require("lib.crypto")local VERSION="v1"local M={}local function urlencode(s)return(tostring(s):gsub("[^%w%-%._~]",function(c)return string.format("%%%02X",c:byte())end))end M.urlencode=urlencode local function form(t,order)local out={}for _,k in ipairs(order)do out[#out+1]=k.."="..urlencode(t[k])end return table.concat(out,"&")end function M.baseHost(serverUrl)local url=(serverUrl or""):match("^%s*(.-)%s*$")local scheme,host=url:match("^(%a+://)([^/]+)")if not scheme then return url end return scheme..host:gsub("^portal%.","api.")end function M.portalHost(serverUrl)local base=M.baseHost(serverUrl)local scheme,rest=base:match("^(%a+://)(.+)$")return scheme and(scheme..rest:gsub("^api%.","portal.").."/")or base end local function byName(a,b)return a.name:lower()<b.name:lower()end local Client={}Client.__index=Client function M.new(serverUrl)return setmetatable({base=M.baseHost(serverUrl)},Client)end function Client:_send(url,req,failure)req.url=url local code,body,_,err=Http.requestSync(req)if code==0 then error({message=failure.." (network error: "..tostring(err)..")"},0)end local ok,decoded=pcall(json.decode,body or"")if code<200 or code>=300 or not ok or type(decoded)~="table"then local detail=(ok and type(decoded)=="table"and(decoded.message or(decoded.reason_code and("reason code "..decoded.reason_code))))or("HTTP "..tostring(code))error({message=detail.."\n"..failure,status=code},0)end return decoded end function Client:authorizeUrl(clientId,redirectUri,scope,state,challenge)return self.base.."/oauth/authorize?"..form({response_type="code",client_id=clientId,redirect_uri=redirectUri,scope=scope,state=state,code_challenge=challenge,code_challenge_method="S256",},{"response_type","client_id","redirect_uri","scope","state","code_challenge","code_challenge_method"})end function Client:exchangeCode(clientId,redirectUri,code,verifier)local body=form({client_id=clientId,grant_type="authorization_code",redirect_uri=redirectUri,code=code,code_verifier=verifier,},{"client_id","grant_type","redirect_uri","code","code_verifier"})local res=self:_send(self.base.."/oauth/token",{method="POST",headers={["Content-Type"]="application/x-www-form-urlencoded",Accept="application/json"},body=body,},"Failed to exchange code for token.")if not res.access_token then error({message="Failed to exchange code for token."},0)end return tostring(res.access_token)end function Client:userInfo(accessToken)local user=self:_send(self.base.."/user/me",{method="GET",headers={Authorization="Bearer "..accessToken,Accept="application/json"},},"Failed to fetch user info.")local info=user.team_info or{}local teams={}for _,t in ipairs(info.available_teams or{})do teams[#teams+1]={id=tostring(t.teamId or""),name=tostring(t.teamName or"")}end table.sort(teams,byName)return{email=tostring(user.email or""),currentTeamId=tostring((info.current_team or{}).teamId or""),teams=teams,}end function Client:tempApiKey(accessToken,teamId)local res=self:_send(self.base.."/user/add-temp-api-key?teamId="..urlencode(teamId),{method="POST",headers={Authorization="Bearer "..accessToken,Accept="application/json"},body="",},"Failed to obtain a Builder API key for this team. Please ensure Builder API is enabled on the Team Setup -> Team Info screen.")for _,entry in pairs(res.apiKey or{})do if type(entry)=="table"and entry.apiKey then return tostring(entry.apiKey)end end error({message="Builder API key not found in response."},0)end function Client:_builder(method,path,body,email,apiKey,failure)return self:_send(self.base..path,{method=method,headers={Authorization="Basic "..crypto.b64(email..":"..apiKey),["Content-Type"]="application/json",Accept="application/json",},body=body,},failure)end function Client:apps(email,apiKey,teamId)local res=self:_builder("GET","/builder/"..VERSION.."/team/"..urlencode(teamId).."/app",nil,email,apiKey,"Failed to fetch app list.")local apps={}for _,a in ipairs((res.response or{}).apps or{})do apps[#apps+1]={id=tostring(a.appId),name=tostring(a.appName or"")}end table.sort(apps,byName)return apps end function Client:appCredential(email,apiKey,teamId,appId)local res=self:_builder("GET","/builder/"..VERSION.."/team/"..urlencode(teamId).."/app/"..urlencode(appId).."/appsecret",nil,email,apiKey,"Failed to fetch app credentials.")local value=((res.response or{}).app or{}).appSecret if not value then error({message="App credentials not found in response."},0)end return tostring(value)end function Client:createApp(email,apiKey,teamId,appName,platforms)local body=json.encode({appName=appName,appOptions={supportedPlatforms=json.array(platforms or{}),gamificationEnabled=true},})local res=self:_builder("POST","/builder/"..VERSION.."/team/"..urlencode(teamId).."/app",body,email,apiKey,"Failed to create app.")return tostring(((res.response or{}).app or{}).appId or"")end return M
